package api

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-netpolicy-guard/internal/store"
)

// Error codes published by the service contract in README.md.
const (
	codeInvalidInput = "InvalidNetPolicyInputError"
	codeConflict     = "NetPolicyConflictError"
	codeNotFound     = "NetPolicyNotFoundError"
	codeStorage      = "storage_unavailable"
)

// NewRouter wires the public HTTP surface. The service contract in README.md
// describes the error shape every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	router.POST("/v1/net-policies", func(c *gin.Context) {
		rec, ok := decodeNetPolicy(c.Request.Body)
		if !ok {
			writeError(c, http.StatusBadRequest, codeInvalidInput, "request body is not a valid net policy")
			return
		}
		stored, created, err := st.Register(rec)
		if errors.Is(err, store.ErrConflict) {
			writeError(c, http.StatusConflict, codeConflict, "a different net policy already exists for this namespace and name")
			return
		}
		if err != nil {
			writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
			return
		}
		status := http.StatusOK
		if created {
			status = http.StatusCreated
		}
		c.JSON(status, stored)
	})

	router.GET("/v1/net-policies", func(c *gin.Context) {
		namespace, label, ok := parseNetPolicyQuery(c.Request.URL.RawQuery)
		if !ok {
			writeError(c, http.StatusBadRequest, codeInvalidInput, "query must be well-formed and carry a single non-blank namespace or label")
			return
		}
		records, err := st.List(namespace, label)
		if err != nil {
			writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
			return
		}
		if len(records) == 0 {
			writeError(c, http.StatusNotFound, codeNotFound, "no net policies match the query")
			return
		}
		c.JSON(http.StatusOK, gin.H{"items": records})
	})

	router.NoRoute(func(c *gin.Context) {
		writeError(c, http.StatusNotFound, "route_not_found", "no route matches this path")
	})
	return router
}

func writeError(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// parseNetPolicyQuery strictly parses the raw query string for the GET entry.
// The whole query must validate before any record is returned: every segment
// needs valid percent escapes in both name and value, and no segment may carry
// an unescaped semicolon — a malformed fragment rejects the request even when
// it belongs to an unknown parameter or the remaining conditions would have
// matched committed records. Empty segments (including a trailing &) are
// skipped. Names are compared after a single decode, so "namespace" and
// "%6Eamespace" are the same parameter; a known parameter may appear at most
// once with a non-blank value, and at least one of namespace/label must be
// present. Legal unknown parameters are ignored. Values are decoded exactly
// once (+ means space) and matched verbatim — no trimming or case folding.
func parseNetPolicyQuery(rawQuery string) (namespace, label string, ok bool) {
	seen := map[string]bool{}
	values := map[string]string{}
	for _, segment := range strings.Split(rawQuery, "&") {
		if segment == "" {
			continue
		}
		if strings.Contains(segment, ";") {
			return "", "", false
		}
		name, value, _ := strings.Cut(segment, "=")
		decodedName, err := url.QueryUnescape(name)
		if err != nil {
			return "", "", false
		}
		decodedValue, err := url.QueryUnescape(value)
		if err != nil {
			return "", "", false
		}
		if decodedName != "namespace" && decodedName != "label" {
			continue
		}
		if seen[decodedName] || strings.TrimSpace(decodedValue) == "" {
			return "", "", false
		}
		seen[decodedName] = true
		values[decodedName] = decodedValue
	}
	namespace, label = values["namespace"], values["label"]
	if namespace == "" && label == "" {
		return "", "", false
	}
	return namespace, label, true
}

// decodeNetPolicy strictly validates the request body: a single JSON object
// with the required fields, enums, and port intervals from the service contract.
//
// The top-level object is walked with a streaming decoder instead of a plain
// map decode so every occurrence of pluginParams is validated on its own: a
// later object must not overwrite an earlier illegal one before that earlier
// object is checked, so {"mode":null} followed by {"mode":"enforce"} fails.
// Field names match after JSON unescaping, making "pluginParams" and
// "\u0070luginParams" the same field. When every occurrence is legal the last
// complete object wins. Other fields keep their existing single-value
// parsing behaviour (a repeated name keeps its last value).
func decodeNetPolicy(body io.Reader) (store.Record, bool) {
	decoder := json.NewDecoder(body)
	opening, err := decoder.Token()
	if err != nil {
		return store.Record{}, false
	}
	if delim, ok := opening.(json.Delim); !ok || delim != '{' {
		// Rejects empty input, null, scalars and arrays outright.
		return store.Record{}, false
	}

	raw := map[string]json.RawMessage{}
	var (
		pluginParams    map[string]string
		pluginParamsSet bool
	)
	for decoder.More() {
		keyToken, err := decoder.Token()
		if err != nil {
			return store.Record{}, false
		}
		key, ok := keyToken.(string)
		if !ok {
			return store.Record{}, false
		}
		var blob json.RawMessage
		if err := decoder.Decode(&blob); err != nil {
			return store.Record{}, false
		}
		if key == "pluginParams" {
			// Validate each occurrence immediately: an illegal object must be
			// rejected even when a later legal object would overwrite it.
			params, valid := decodePluginObject(blob)
			if !valid {
				return store.Record{}, false
			}
			pluginParams, pluginParamsSet = params, true
		}
		raw[key] = blob
	}
	closing, err := decoder.Token()
	if err != nil {
		return store.Record{}, false
	}
	if delim, ok := closing.(json.Delim); !ok || delim != '}' {
		return store.Record{}, false
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return store.Record{}, false
	}

	var rec store.Record
	var ok bool
	if rec.Namespace, ok = requiredString(raw, "namespace"); !ok {
		return store.Record{}, false
	}
	if rec.Name, ok = requiredString(raw, "name"); !ok {
		return store.Record{}, false
	}
	if rec.Label, ok = requiredString(raw, "label"); !ok {
		return store.Record{}, false
	}
	if rec.Rules, ok = decodeRules(raw); !ok {
		return store.Record{}, false
	}
	if !pluginParamsSet {
		return store.Record{}, false
	}
	rec.PluginParams = pluginParams
	return rec, true
}

// requiredString reads a present, non-blank JSON string field.
func requiredString(raw map[string]json.RawMessage, key string) (string, bool) {
	blob, present := raw[key]
	if !present {
		return "", false
	}
	var value string
	if err := json.Unmarshal(blob, &value); err != nil {
		return "", false
	}
	if strings.TrimSpace(value) == "" {
		return "", false
	}
	return value, true
}

func decodeRules(raw map[string]json.RawMessage) ([]store.Rule, bool) {
	blob, present := raw["rules"]
	if !present {
		return nil, false
	}
	var items []json.RawMessage
	if err := json.Unmarshal(blob, &items); err != nil || len(items) == 0 {
		return nil, false
	}
	rules := make([]store.Rule, 0, len(items))
	for _, item := range items {
		var fields map[string]json.RawMessage
		if err := json.Unmarshal(item, &fields); err != nil {
			return nil, false
		}
		direction, ok := requiredEnum(fields, "direction", "ingress", "egress")
		if !ok {
			return nil, false
		}
		action, ok := requiredEnum(fields, "action", "allow", "deny")
		if !ok {
			return nil, false
		}
		portsBlob, present := fields["ports"]
		if !present {
			return nil, false
		}
		var ports []int
		if err := json.Unmarshal(portsBlob, &ports); err != nil || len(ports) != 2 {
			return nil, false
		}
		if ports[0] < 1 || ports[0] > 65535 || ports[1] < 1 || ports[1] > 65535 || ports[0] > ports[1] {
			return nil, false
		}
		rules = append(rules, store.Rule{Direction: direction, Action: action, Ports: [2]int{ports[0], ports[1]}})
	}
	return rules, true
}

// requiredEnum reads a present JSON string field restricted to the given values.
func requiredEnum(raw map[string]json.RawMessage, key string, allowed ...string) (string, bool) {
	blob, present := raw[key]
	if !present {
		return "", false
	}
	var value string
	if err := json.Unmarshal(blob, &value); err != nil {
		return "", false
	}
	for _, candidate := range allowed {
		if value == candidate {
			return value, true
		}
	}
	return "", false
}

// decodePluginObject validates and decodes one pluginParams value. The
// published contract is a string-to-string object: null, numbers, booleans,
// arrays and nested objects are invalid input rather than coerced or dropped.
//
// Members are walked with a streaming decoder so every occurrence of a repeated
// member name is inspected, not just the value a map decode would keep last.
// {"mode":null,"mode":"enforce"} must fail on the null even though a legal
// string follows it; keys are matched after JSON unescaping, so "mode" and
// "\u006dode" are the same member. When every occurrence is a string the last
// value for each decoded key wins, and the empty object yields an empty map.
func decodePluginObject(blob json.RawMessage) (map[string]string, bool) {
	decoder := json.NewDecoder(bytes.NewReader(blob))
	opening, err := decoder.Token()
	if err != nil {
		return nil, false
	}
	delim, ok := opening.(json.Delim)
	if !ok || delim != '{' {
		// Rejects null, scalars and arrays outright.
		return nil, false
	}

	params := map[string]string{}
	for decoder.More() {
		keyToken, err := decoder.Token()
		if err != nil {
			return nil, false
		}
		key, ok := keyToken.(string)
		if !ok {
			return nil, false
		}
		valueToken, err := decoder.Token()
		if err != nil {
			return nil, false
		}
		value, ok := valueToken.(string)
		if !ok {
			return nil, false
		}
		params[key] = value
	}
	if _, err := decoder.Token(); err != nil {
		return nil, false
	}

	// The RawMessage must contain exactly the object and nothing trailing.
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return nil, false
	}
	return params, true
}

package api

// Strict query parsing regression tests for GET /v1/net-policies: the whole
// query string must validate before any record is returned, legal encodings
// keep the original matching semantics, and queries never mutate the registry.

import (
	"net/http"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/Bob-xisuke/orb-netpolicy-guard/internal/store"
)

// A malformed fragment rejects the whole query no matter where it sits —
// first, middle or last segment, in a name or a value, in a known or an
// unknown parameter — and no matter whether the remaining conditions would
// have matched committed records. The committed records, their order and
// their conflict flags stay untouched.
func TestGetNetPoliciesRejectsMalformedQuerySegments(t *testing.T) {
	router, _ := newTestRouter(t)
	deny := registerCreated(t, router,
		singleRuleBody("payments", "default-deny", "tier=backend", "ingress", "deny", 80, 100, `{"mode": "enforce"}`),
		1, false)
	allow := registerCreated(t, router,
		singleRuleBody("payments", "allow-web", "tier=backend", "ingress", "allow", 100, 200, `{"mode": "enforce"}`),
		2, true)

	cases := map[string]string{
		// The headline case: a matching record exists, yet the bad escape
		// in the repeated parameter must not return it.
		"bad escape after matching namespace": "/v1/net-policies?namespace=payments&namespace=%ZZ",
		"bad escape in first segment":         "/v1/net-policies?namespace=%ZZ&namespace=payments",
		"bad escape in middle segment":        "/v1/net-policies?namespace=payments&junk=%2&label=tier%3Dbackend",
		"bad escape in last segment":          "/v1/net-policies?namespace=payments&junk=%",
		"incomplete escape at end of value":   "/v1/net-policies?namespace=paymen%7",
		"lone percent in value":               "/v1/net-policies?namespace=pay%ments",
		"non-hex escape in value":             "/v1/net-policies?namespace=pay%GGments",
		"bad escape in unknown param name":    "/v1/net-policies?%ZZ=x&namespace=payments",
		"bad escape in unknown param value":   "/v1/net-policies?junk=%ZZ&namespace=payments",
		"bad escape with non-matching filter": "/v1/net-policies?namespace=missing&junk=%ZZ",
		"semicolon in value":                  "/v1/net-policies?namespace=payments;extra",
		"semicolon in unknown param":          "/v1/net-policies?namespace=payments&junk=a;b",
		"semicolon in name":                   "/v1/net-policies?name;space=payments",
		"semicolon only segment":              "/v1/net-policies?namespace=payments&;",
		"duplicate identical value":           "/v1/net-policies?namespace=payments&namespace=payments",
		"duplicate via encoded name":          "/v1/net-policies?namespace=payments&%6Eamespace=payments",
		"duplicate label identical value":     "/v1/net-policies?label=tier%3Dbackend&label=tier%3Dbackend",
		"empty value":                         "/v1/net-policies?namespace=",
		"whitespace value from plus":          "/v1/net-policies?namespace=+",
		"whitespace value from escape":        "/v1/net-policies?namespace=%20",
		"no condition, only unknown param":    "/v1/net-policies?junk=x",
	}
	for name, target := range cases {
		t.Run(name, func(t *testing.T) {
			recorder := doRequest(router, http.MethodGet, target, "")
			if recorder.Code != http.StatusBadRequest {
				t.Fatalf("GET %s status = %d, want %d: %s",
					target, recorder.Code, http.StatusBadRequest, recorder.Body.String())
			}
			assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
			assertSafeErrorMessage(t, recorder)
		})
	}

	// The rejected queries changed nothing: both committed records come back
	// untouched — content, order and conflict flags included.
	items := listItems(t, router, "/v1/net-policies?namespace=payments")
	if want := []map[string]any{deny, allow}; !reflect.DeepEqual(items, want) {
		t.Fatalf("items after rejected queries = %v, want unchanged %v", items, want)
	}
}

// Legal queries keep the original matching semantics: + means space, %2B/%3B/%26
// are literal +, ; and & inside values rather than separators or illegal input,
// parameters decode exactly once, and the decoded value matches verbatim —
// surrounding spaces and letter case are significant. Legal unknown parameters
// are ignored, and empty segments (including a trailing &) change nothing.
func TestGetNetPoliciesLegalEncodingSemantics(t *testing.T) {
	router, _ := newTestRouter(t)

	spaced := registerCreated(t, router,
		singleRuleBody("pay ments", "spaced", "tier=backend", "ingress", "allow", 80, 80, `{}`), 1, false)
	special := registerCreated(t, router,
		singleRuleBody("payments", "special", "a+b;c&d", "ingress", "allow", 80, 80, `{}`), 2, false)
	plain := registerCreated(t, router,
		singleRuleBody("payments", "plain", "tier=backend", "ingress", "allow", 80, 80, `{}`), 3, false)

	// + decodes to a space.
	items := listItems(t, router, "/v1/net-policies?namespace=pay+ments")
	if len(items) != 1 || !reflect.DeepEqual(items[0], spaced) {
		t.Fatalf("plus-as-space items = %v, want %v", items, spaced)
	}

	// %2B, %3B and %26 are literal characters inside a value, not separators.
	items = listItems(t, router, "/v1/net-policies?label=a%2Bb%3Bc%26d")
	if len(items) != 1 || !reflect.DeepEqual(items[0], special) {
		t.Fatalf("escaped-separator items = %v, want %v", items, special)
	}

	// The escaped & and ; above did not split parameters: intersecting with a
	// namespace condition still works on the decoded value.
	items = listItems(t, router, "/v1/net-policies?namespace=payments&label=a%2Bb%3Bc%26d")
	if len(items) != 1 || !reflect.DeepEqual(items[0], special) {
		t.Fatalf("intersection items = %v, want %v", items, special)
	}

	// Parameters decode exactly once: %252B is the literal text "%2B", not "+".
	miss := doRequest(router, http.MethodGet, "/v1/net-policies?label=a%252Bb%253Bc%2526d", "")
	if miss.Code != http.StatusNotFound {
		t.Fatalf("double-encoded status = %d, want %d", miss.Code, http.StatusNotFound)
	}
	assertErrorCode(t, miss, "NetPolicyNotFoundError")

	// Decoded values match verbatim: no trimming, no case folding.
	for _, target := range []string{
		"/v1/net-policies?namespace=+payments", // leading space is significant
		"/v1/net-policies?namespace=payments+", // trailing space is significant
		"/v1/net-policies?namespace=Payments",  // case is significant
	} {
		recorder := doRequest(router, http.MethodGet, target, "")
		if recorder.Code != http.StatusNotFound {
			t.Fatalf("GET %s status = %d, want %d", target, recorder.Code, http.StatusNotFound)
		}
		assertErrorCode(t, recorder, "NetPolicyNotFoundError")
	}

	// Legal unknown parameters are ignored; empty segments and a trailing &
	// do not change the result.
	want := []map[string]any{special, plain}
	for _, target := range []string{
		"/v1/net-policies?namespace=payments&verbose=true&empty=",
		"/v1/net-policies?namespace=payments&unknown=%2B%3B%26",
		"/v1/net-policies?&namespace=payments&&",
		"/v1/net-policies?namespace=payments&",
	} {
		if items := listItems(t, router, target); !reflect.DeepEqual(items, want) {
			t.Fatalf("GET %s items = %v, want %v", target, items, want)
		}
	}
}

// With the storage layer down a well-formed query reports 503
// storage_unavailable, while a malformed query is still rejected with 400
// before any storage access.
func TestGetNetPoliciesStorageUnavailable(t *testing.T) {
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	router := NewRouter(st)
	if err := st.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}

	recorder := doRequest(router, http.MethodGet, "/v1/net-policies?namespace=payments", "")
	if recorder.Code != http.StatusServiceUnavailable {
		t.Fatalf("legal query status = %d, want %d: %s",
			recorder.Code, http.StatusServiceUnavailable, recorder.Body.String())
	}
	assertExactErrorShape(t, recorder, "storage_unavailable")
	assertSafeErrorMessage(t, recorder)

	recorder = doRequest(router, http.MethodGet, "/v1/net-policies?namespace=payments&namespace=%ZZ", "")
	if recorder.Code != http.StatusBadRequest {
		t.Fatalf("illegal query status = %d, want %d: %s",
			recorder.Code, http.StatusBadRequest, recorder.Body.String())
	}
	assertExactErrorShape(t, recorder, "InvalidNetPolicyInputError")
	assertSafeErrorMessage(t, recorder)
}

