438				seedParams:  `{"mode": "enforce", "retries": "3"}`,
439				retryParams: `{"mode": "enforce", "retries": null}`,
440			},
441			{
442				name:        "first member null alongside legal string",
443				seedParams:  `{"mode": "enforce", "retries": "3"}`,
